fn frame(t: i32) {
    let down: i32 = host::display::pointer_down();
    let prev: i32 = host::display::state_get(0);
    if down == 1 && prev == 0 {
        let hdl: i32 = host::audio::tone(330, 10000, 3);
        host::display::state_set(1, hdl);
    }
    if down == 0 && prev == 1 {
        host::audio::stop(host::display::state_get(1));
    }
    host::display::state_set(0, down);
    let mut bg: i32 = 0x101010;
    if down == 1 { bg = 0x104020; }
    host::display::clear(bg);
    if down == 1 {
        host::display::draw_string(8, 10, "SOUNDING", 0x00ff88, 3);
    } else {
        host::display::draw_string(8, 10, "HOLD FOR NOTE", 0xffffff, 2);
    }
    host::display::present();
}
